import array2tidy = require( './index' );


// TESTS //

// The function returns a data set...
{
	array2tidy( [ 1, 2, 3 ], 'data', [ 'index', 'value' ] ); // $ExpectType DataSet
}

// The compiler throws an error if the function is provided a first argument which is not a collection...
{
	array2tidy( 5, 'data', [ 'index', 'value' ] ); // $ExpectError
	array2tidy( true, 'data', [ 'index', 'value' ] ); // $ExpectError
	array2tidy( false, 'data', [ 'index', 'value' ] ); // $ExpectError
	array2tidy( null, 'data', [ 'index', 'value' ] ); // $ExpectError
	array2tidy( {}, 'data', [ 'index', 'value' ] ); // $ExpectError
	array2tidy( ( x: number ): number => x, 'data', [ 'index', 'value' ] ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a string...
{
	array2tidy( [ 1, 2, 3 ], 5, [ 'index', 'value' ] ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], true, [ 'index', 'value' ] ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], false, [ 'index', 'value' ] ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], null, [ 'index', 'value' ] ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], [], [ 'index', 'value' ] ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], {}, [ 'index', 'value' ] ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], ( x: number ): number => x, [ 'index', 'value' ] ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not an array of strings...
{
	array2tidy( [ 1, 2, 3 ], 'data', 5 ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], 'data', true ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], 'data', false ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], 'data', null ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], 'data', {} ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], 'data', [ 1, 2 ] ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], 'data', ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	array2tidy(); // $ExpectError
	array2tidy( [ 1, 2, 3 ] ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], 'data' ); // $ExpectError
	array2tidy( [ 1, 2, 3 ], 'data', [ 'index', 'value' ], {} ); // $ExpectError
}
